  font-size: 14px;
  font-weight: 500;
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
@media (max-width: 834px) {
  .entertainment-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .entertainment-cards { grid-template-columns: 1fr; }
}

/* --- Savings / Special Stores Cards --- */
.savings-card {
  flex: 0 0 280px;
  border-radius: 18px;
  background: #f5f5f7;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.savings-card h4 { font-size: 17px; font-weight: 600; }
.savings-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.savings-card a { font-size: 14px; font-weight: 500; }

/* --- Quick Links --- */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 40px 22px;
  border-top: 1px solid #d2d2d7;
}
.quick-link-btn {
  padding: 10px 20px;
  border: 1px solid #d2d2d7;
  border-radius: 980px;
  font-size: 14px;
  color: #1d1d1f;
  transition: background .3s;
}
.quick-link-btn:hover { background: #f5f5f7; text-decoration: none; }
.quick-link-btn i { margin-right: 4px; }

/* --- Shopping Guide Cards --- */
.guide-card {
  flex: 0 0 280px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
}
.guide-card-image {
  width: 100%;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f5f7;
}
.guide-card-image i { font-size: 48px; color: #1d1d1f; opacity: .4; }
.guide-card-body { padding: 20px; }
.guide-card-body h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.guide-card-body p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.guide-card-body a { font-size: 14px; margin-top: 8px; display: inline-block; }

/* --- Setup & Experience Cards --- */
.setup-card {
  flex: 0 0 280px;
  border-radius: 18px;
  background: #f5f5f7;
  padding: 28px 24px;
}
.setup-card i { font-size: 28px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.setup-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.setup-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }

/* --- Sticky Section Nav (Category pages) --- */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 900;
  background: rgba(255,255,255,.9);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid #d2d2d7;
}
.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 0;
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav a {
  padding: 12px 20px;
  font-size: 14px;
  color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color .3s, border-color .3s;
}
.section-nav a:hover { color: #1d1d1f; text-decoration: none; }
.section-nav a.active { color: #1d1d1f; font-weight: 600; border-bottom-color: #1d1d1f; }

/* --- Footer --- */
.site-footer {
  background: #f5f5f7;
  padding: 20px 0 30px;
  border-top: 1px solid #d2d2d7;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.footer-legal {
  font-size: 12px;
  color: #6e6e73;
  line-height: 1.5;
  padding-bottom: 16px;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 16px;
}
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 16px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: #1d1d1f;
  margin-bottom: 8px;
}
.footer-col ul li { margin-bottom: 4px; }
.footer-col ul li a { font-size: 12px; color: #6e6e73; }
.footer-col ul li a:hover { color: #1d1d1f; text-decoration: underline; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #6e6e73;
  flex-wrap: wrap;
  gap: 8px;
}

/* Footer accordion on mobile */
@media (max-width: 834px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col { border-bottom: 1px solid #d2d2d7; }
  .footer-col h5 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }
  .footer-col h5::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform .3s;
  }
  .footer-col.open h5::after { content: '−'; }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .3s ease;
  }
  .footer-col.open ul { max-height: 500px; }
}

/* --- SVG Product Placeholders --- */
.product-svg {
  width: 60%;
  max-width: 200px;
  height: auto;
  opacity: .85;
}
.product-svg-sm {
  width: 50%;
  max-width: 120px;
  height: auto;
  opacity: .7;
}

/* --- Accessory Card --- */
.accessory-card {
  flex: 0 0 200px;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
  overflow: hidden;
  text-align: center;
  padding-bottom: 16px;
}
.accessory-card .card-image {
  height: 200px;
  background: #f5f5f7;
}
.accessory-card .card-image i { font-size: 48px; color: #1d1d1f; opacity: .5; }
.accessory-card .card-body { padding: 12px 16px; }
.accessory-card .card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.3; }
.accessory-card .card-body .price { font-size: 14px; font-weight: 600; margin-top: 4px; }

/* --- Audio Card --- */
.audio-card {
  flex: 0 0 240px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
}
.audio-card .card-image {
  height: 240px;
}
.audio-card .card-image i { font-size: 64px; opacity: .6; }
.audio-card .card-body { padding: 16px 20px; }
.audio-card .card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.3; }
.audio-card .card-body .price { font-size: 14px; font-weight: 600; margin-top: 4px; }
.audio-card .card-body .note { font-size: 12px; color: #6e6e73; margin-top: 2px; }

/* --- Model Cards (category pages) --- */
.model-card {
  flex: 0 0 300px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
  text-align: center;
}
.model-card .card-image { height: 300px; }
.model-card .card-image i { font-size: 80px; opacity: .6; }
.model-card .card-body { padding: 20px 24px 28px; }
.model-card .card-body .badge-new { margin-bottom: 4px; }
.model-card .card-body h4 { font-size: 21px; font-weight: 600; margin-bottom: 4px; }
.model-card .card-body .price { font-size: 17px; font-weight: 600; }
.model-card .card-body .price-monthly { font-size: 14px; color: #6e6e73; margin-top: 2px; }
.model-card .card-body .card-links { margin-top: 12px; display: flex; justify-content: center; gap: 16px; }

/* --- Experience Section --- */
.experience-section {
  text-align: center;
  padding: 80px 22px;
  background: #f5f5f7;
}
.experience-section h2 { font-size: 40px; font-weight: 700; }
.experience-section p { font-size: 21px; color: #6e6e73; margin-top: 6px; }
.experience-features {
  display: flex;
  justify-content: center;
  gap: 40px;
  margin-top: 40px;
  flex-wrap: wrap;
}
.experience-feature {
  text-align: center;
  max-width: 200px;
}
.experience-feature i { font-size: 40px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.experience-feature h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.experience-feature p { font-size: 14px; color: #6e6e73; }

/* --- Special Stores --- */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.special-store-card {
  border-radius: 18px;
  background: #f5f5f7;
  padding: 32px 24px;
  text-align: center;
}
.special-store-card i { font-size: 36px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.special-store-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.special-store-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.special-store-card a { font-size: 14px; margin-top: 8px; display: inline-block; }

@media (max-width: 768px) {
  .special-stores-grid { grid-template-columns: 1fr; }
}

/* --- Category Page Sections --- */
.category-section {
  padding: 60px 0;
  scroll-margin-top: 90px;
}
.category-section:nth-child(even) { background: #f5f5f7; }

/* --- Utility --- */
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
.link-blue { color: #0066cc; }
.link-white { color: #2997ff; }
