.link-blue { color: #0066cc; }
.link-white { color: #2997ff; }

/* ========================================
   Orchard — Premium Tech E-Commerce Store
   ======================================== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47059;
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: #0066cc; text-decoration: none; }
a:hover { text-decoration: underline; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* --- Typography --- */
.headline { font-size: 56px; font-weight: 700; letter-spacing: -0.005em; line-height: 1.07143; }
.headline-sm { font-size: 48px; font-weight: 700; letter-spacing: -0.003em; line-height: 1.08349; }
.subheadline { font-size: 28px; font-weight: 400; letter-spacing: .011em; line-height: 1.10722; color: #6e6e73; }
.subheadline-sm { font-size: 21px; font-weight: 400; line-height: 1.381; color: #6e6e73; }
.section-eyebrow { font-size: 12px; font-weight: 600; letter-spacing: -.01em; text-transform: uppercase; color: #6e6e73; margin-bottom: 4px; }
.badge-new { display: inline-block; font-size: 12px; font-weight: 600; color: #bf4800; letter-spacing: -.01em; margin-bottom: 2px; }
.price { font-size: 14px; color: #1d1d1f; }
.price-monthly { font-size: 14px; color: #6e6e73; margin-top: 2px; }

@media (max-width: 768px) {
  .headline { font-size: 36px; }
  .headline-sm { font-size: 32px; }
  .subheadline { font-size: 19px; }
  .subheadline-sm { font-size: 17px; }
}

/* --- Layout --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 22px; }
.section { padding: 80px 0; }
.section-alt { background: #f5f5f7; }

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: #f5f5f7;
  text-align: center;
  padding: 12px 22px;
  font-size: 14px;
  color: #1d1d1f;
  border-bottom: 1px solid #d2d2d7;
}
.ribbon-banner a { color: #0066cc; font-weight: 500; }

/* --- Top Navigation --- */
.top-nav {
  background: rgba(255,255,255,.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid #d2d2d7;
}
.top-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
}
.nav-logo {
  font-size: 21px;
  font-weight: 600;
  color: #1d1d1f;
  letter-spacing: -.01em;
}
.nav-links { display: flex; gap: 28px; align-items: center; }
.nav-links a {
  font-size: 12px;
  font-weight: 400;
  color: #1d1d1f;
  letter-spacing: 0;
  transition: color .3s;
}
.nav-links a:hover { color: #0066cc; text-decoration: none; }
.nav-icons { display: flex; gap: 18px; align-items: center; }
.nav-icons i { font-size: 18px; color: #1d1d1f; }
.nav-icons a:hover i { color: #0066cc; }

/* Mobile nav toggle */
.nav-toggle { display: none; font-size: 22px; color: #1d1d1f; padding: 8px; }
@media (max-width: 834px) {
  .nav-links { display: none; }
  .nav-toggle { display: block; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 44px;
    left: 0;
    right: 0;
    background: rgba(255,255,255,.95);
    backdrop-filter: blur(20px);
    padding: 16px 22px;
    gap: 12px;
    border-bottom: 1px solid #d2d2d7;
  }
  .nav-links.open a { font-size: 17px; padding: 8px 0; }
}

/* --- Hero Sections --- */
.hero-section {
  text-align: center;
  padding: 80px 22px 40px;
}
.hero-section h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.07143;
}
.hero-section p {
  font-size: 28px;
  color: #6e6e73;
  margin-top: 6px;
}
.hero-ctas {
  display: flex;
  justify-content: center;
  gap: 28px;
  margin-top: 20px;
  flex-wrap: wrap;
}
.hero-ctas a { font-size: 21px; font-weight: 400; }
@media (max-width: 768px) {
  .hero-section h1 { font-size: 36px; }
  .hero-section p { font-size: 19px; }
  .hero-ctas a { font-size: 17px; }
}

/* Category hero with gradient */
.category-hero {
  text-align: center;
  padding: 90px 22px 50px;
  background: linear-gradient(180deg, #000 0%, #1a1a2e 100%);
  color: #fff;
}
.category-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.07143;
}
.category-hero p {
  font-size: 28px;
  color: #a1a1a6;
  margin-top: 6px;
}

/* --- Product Grid (Homepage) --- */
.product-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px 40px;
}
.product-tile {
  border-radius: 18px;
  overflow: hidden;
  text-align: center;
  padding: 44px 24px 0;
  min-height: 580px;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}
.product-tile h3 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -.002em;
  line-height: 1.1;
}
.product-tile .tile-tagline {
  font-size: 21px;
  color: #6e6e73;
  margin-top: 4px;
  font-weight: 400;
}
.tile-ctas {
  display: flex;
  gap: 24px;
  margin-top: 14px;
  margin-bottom: 20px;
}
.tile-ctas a { font-size: 17px; }
.tile-image {
  flex: 1;
  width: 100%;
  min-height: 300px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

/* Product tile gradients */
.tile-phone { background: linear-gradient(180deg, #fbfbfd 0%, #f0f0f2 100%); color: #1d1d1f; }
.tile-laptop-neo { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); color: #1d1d1f; }
.tile-tablet-pro { background: linear-gradient(180deg, #000 0%, #1d1d2c 100%); color: #fff; }
.tile-tablet-pro .tile-tagline { color: #a1a1a6; }
.tile-laptop-pro { background: linear-gradient(180deg, #1a1a2e 0%, #0d0d1a 100%); color: #fff; }
.tile-laptop-pro .tile-tagline { color: #a1a1a6; }
.tile-earbuds { background: linear-gradient(180deg, #fafafa 0%, #ebebf0 100%); color: #1d1d1f; }
.tile-tradein { background: linear-gradient(180deg, #f5f5f7 0%, #e3e3e8 100%); color: #1d1d1f; }

@media (max-width: 768px) {
  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 480px; }
  .product-tile h3 { font-size: 32px; }
  .tile-image { min-height: 240px; }
}

/* --- Product Icon Bar --- */
.product-bar {
  background: #fff;
  border-bottom: 1px solid #d2d2d7;
  position: sticky;
  top: 44px;
  z-index: 900;
}
.product-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  overflow-x: auto;
  gap: 0;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.product-bar-inner::-webkit-scrollbar { display: none; }
.product-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 16px 20px 12px;
  min-width: 100px;
  font-size: 12px;
  color: #1d1d1f;
  text-decoration: none;
  white-space: nowrap;
  transition: color .3s;
}
.product-bar-item:hover { color: #0066cc; text-decoration: none; }
.product-bar-item .bar-icon {
  width: 48px;
  height: 48px;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.product-bar-item .bar-icon i { font-size: 36px; }

/* --- Section Headers --- */
.section-header {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  margin-bottom: 20px;
}
.section-header h2 {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -.002em;
  line-height: 1.1;
}
.section-header p {
  font-size: 21px;
  color: #6e6e73;
  margin-top: 4px;
}
.section-header .promo {
  font-size: 14px;
  color: #6e6e73;
  margin-top: 8px;
}
.section-header .promo a { font-weight: 500; }
@media (max-width: 768px) {
  .section-header h2 { font-size: 28px; }
  .section-header p { font-size: 17px; }
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding: 4px 0 20px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-60%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,.9);
  box-shadow: 0 1px 4px rgba(0,0,0,.16);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: opacity .3s, transform .2s;
  font-size: 20px;
  color: #1d1d1f;
}
.carousel-arrow:hover { transform: translateY(-60%) scale(1.06); }
.carousel-arrow-left { left: 4px; }
.carousel-arrow-right { right: 4px; }
.carousel-arrow.hidden { opacity: 0; pointer-events: none; }

/* --- Carousel Cards --- */
.carousel-card {
  flex: 0 0 280px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
  transition: transform .3s;
}
.carousel-card:hover { transform: translateY(-2px); }

.card-image {
  width: 100%;
  height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.card-image i { font-size: 80px; opacity: .7; }

.card-body { padding: 20px; }
.card-body .badge-new { margin-bottom: 4px; }
.card-body h4 { font-size: 17px; font-weight: 600; line-height: 1.3; margin-bottom: 2px; }
.card-body .card-tagline { font-size: 14px; color: #6e6e73; margin-bottom: 8px; line-height: 1.3; }
.card-body .price { font-size: 14px; font-weight: 600; }
.card-body .price-monthly { font-size: 12px; color: #6e6e73; margin-top: 2px; }
.card-body .card-links { margin-top: 10px; display: flex; gap: 16px; }
.card-body .card-links a { font-size: 14px; }

/* Card color variants */
.card-bg-light { background: #f5f5f7; }
.card-bg-dark { background: #1d1d1f; color: #fff; }
.card-bg-dark .card-tagline { color: #a1a1a6; }
.card-bg-dark .price-monthly { color: #a1a1a6; }
.card-bg-dark .card-links a { color: #2997ff; }
.card-bg-blue { background: linear-gradient(180deg, #0071e3 0%, #0055b3 100%); color: #fff; }
.card-bg-blue .card-tagline { color: rgba(255,255,255,.8); }
.card-bg-blue .price { color: #fff; }
.card-bg-blue .price-monthly { color: rgba(255,255,255,.7); }
.card-bg-blue .card-links a { color: #fff; }

/* Product image gradient backgrounds */
.img-phone { background: linear-gradient(180deg, #fbfbfd 0%, #f0f0f2 100%); }
.img-laptop { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.img-laptop-dark { background: linear-gradient(180deg, #2a2a3e 0%, #1d1d2c 100%); }
.img-tablet { background: linear-gradient(180deg, #000 0%, #1a1a2e 100%); }
.img-watch { background: linear-gradient(180deg, #f5f5f7 0%, #e8e8ed 100%); }
.img-headphones { background: linear-gradient(180deg, #e8e8ed 0%, #d4d4da 100%); }
.img-headphones-dark { background: linear-gradient(180deg, #1d1d1f 0%, #2a2a2e 100%); }
.img-earbuds { background: linear-gradient(180deg, #fafafa 0%, #ebebf0 100%); }
.img-accessory { background: linear-gradient(180deg, #f5f5f7 0%, #ebebf0 100%); }
.img-speaker { background: linear-gradient(180deg, #f5f5f7 0%, #e0e0e5 100%); }

/* --- Help Cards --- */
.help-card {
  flex: 0 0 280px;
  border-radius: 18px;
  background: #f5f5f7;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.help-card i { font-size: 32px; color: #1d1d1f; }
.help-card h4 { font-size: 17px; font-weight: 600; }
.help-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.help-card a { font-size: 14px; font-weight: 500; }

/* --- Store Difference Cards --- */
.diff-card {
  flex: 0 0 280px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
}
.diff-card-image {
  width: 100%;
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f5f7;
}
.diff-card-image i { font-size: 56px; color: #1d1d1f; opacity: .5; }
.diff-card-body { padding: 20px; }
.diff-card-body h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.diff-card-body p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.diff-card-body a { font-size: 14px; margin-top: 8px; display: inline-block; }

/* --- Brand Collab Section --- */
.brand-collab {
  text-align: center;
  padding: 80px 22px;
  background: linear-gradient(180deg, #1d1d1f 0%, #2a2a3e 100%);
  color: #fff;
}
.brand-collab h2 { font-size: 48px; font-weight: 700; }
.brand-collab p { font-size: 21px; color: #a1a1a6; margin-top: 6px; }
.brand-collab .brand-items {
  display: flex;
  justify-content: center;
  gap: 24px;
  margin-top: 32px;
  flex-wrap: wrap;
}
.brand-item {
  background: rgba(255,255,255,.08);
  border-radius: 14px;
  padding: 24px 28px;
  text-align: center;
  min-width: 180px;
}
.brand-item i { font-size: 40px; margin-bottom: 8px; display: block; }
.brand-item span { font-size: 14px; font-weight: 500; }

/* --- Entertainment Tabs --- */
.entertainment-section {
  padding: 80px 0;
  background: #fff;
}
.entertainment-section .section-header { text-align: center; }
.tab-nav {
  display: flex;
  justify-content: center;
  gap: 0;
  margin: 20px auto 32px;
  max-width: 600px;
  border-bottom: 1px solid #d2d2d7;
}
.tab-btn {
  padding: 10px 24px;
  font-size: 17px;
  font-weight: 400;
  color: #6e6e73;
  border-bottom: 2px solid transparent;
  transition: color .3s, border-color .3s;
}
.tab-btn:hover { color: #1d1d1f; }
.tab-btn.active {
  color: #1d1d1f;
  font-weight: 600;
  border-bottom-color: #1d1d1f;
}
.tab-content { display: none; }
.tab-content.active { display: block; }

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.ent-card {
  border-radius: 14px;
  overflow: hidden;
  position: relative;
  aspect-ratio: 3/4;
  display: flex;
  align-items: flex-end;
}
.ent-card-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.ent-card-content {
  position: relative;
  z-index: 1;
  padding: 20px;
  color: #fff;
  width: 100%;
}
.ent-card-content h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.ent-card-content p { font-size: 12px; color: rgba(255,255,255,.8); margin-bottom: 8px; }
.ent-card-content a {
  font-size: 14px;
  font-weight: 500;
  color: #fff;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
@media (max-width: 834px) {
  .entertainment-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .entertainment-cards { grid-template-columns: 1fr; }
}

/* --- Savings / Special Stores Cards --- */
.savings-card {
  flex: 0 0 280px;
  border-radius: 18px;
  background: #f5f5f7;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.savings-card h4 { font-size: 17px; font-weight: 600; }
.savings-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.savings-card a { font-size: 14px; font-weight: 500; }

/* --- Quick Links --- */
.quick-links {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 40px 22px;
  border-top: 1px solid #d2d2d7;
}
.quick-link-btn {
  padding: 10px 20px;
  border: 1px solid #d2d2d7;
  border-radius: 980px;
  font-size: 14px;
  color: #1d1d1f;
  transition: background .3s;
}
.quick-link-btn:hover { background: #f5f5f7; text-decoration: none; }
.quick-link-btn i { margin-right: 4px; }

/* --- Shopping Guide Cards --- */
.guide-card {
  flex: 0 0 280px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
}
.guide-card-image {
  width: 100%;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f5f5f7;
}
.guide-card-image i { font-size: 48px; color: #1d1d1f; opacity: .4; }
.guide-card-body { padding: 20px; }
.guide-card-body h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.guide-card-body p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.guide-card-body a { font-size: 14px; margin-top: 8px; display: inline-block; }

/* --- Setup & Experience Cards --- */
.setup-card {
  flex: 0 0 280px;
  border-radius: 18px;
  background: #f5f5f7;
  padding: 28px 24px;
}
.setup-card i { font-size: 28px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.setup-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.setup-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }

/* --- Sticky Section Nav (Category pages) --- */
.section-nav {
  position: sticky;
  top: 44px;
  z-index: 900;
  background: rgba(255,255,255,.9);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid #d2d2d7;
}
.section-nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
  display: flex;
  gap: 0;
  overflow-x: auto;
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav a {
  padding: 12px 20px;
  font-size: 14px;
  color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color .3s, border-color .3s;
}
.section-nav a:hover { color: #1d1d1f; text-decoration: none; }
.section-nav a.active { color: #1d1d1f; font-weight: 600; border-bottom-color: #1d1d1f; }

/* --- Footer --- */
.site-footer {
  background: #f5f5f7;
  padding: 20px 0 30px;
  border-top: 1px solid #d2d2d7;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.footer-legal {
  font-size: 12px;
  color: #6e6e73;
  line-height: 1.5;
  padding-bottom: 16px;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 16px;
}
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 16px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: #1d1d1f;
  margin-bottom: 8px;
}
.footer-col ul li { margin-bottom: 4px; }
.footer-col ul li a { font-size: 12px; color: #6e6e73; }
.footer-col ul li a:hover { color: #1d1d1f; text-decoration: underline; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #6e6e73;
  flex-wrap: wrap;
  gap: 8px;
}

/* Footer accordion on mobile */
@media (max-width: 834px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col { border-bottom: 1px solid #d2d2d7; }
  .footer-col h5 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }
  .footer-col h5::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform .3s;
  }
  .footer-col.open h5::after { content: '−'; }
  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .3s ease;
  }
  .footer-col.open ul { max-height: 500px; }
}

/* --- SVG Product Placeholders --- */
.product-svg {
  width: 60%;
  max-width: 200px;
  height: auto;
  opacity: .85;
}
.product-svg-sm {
  width: 50%;
  max-width: 120px;
  height: auto;
  opacity: .7;
}

/* --- Accessory Card --- */
.accessory-card {
  flex: 0 0 200px;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
  overflow: hidden;
  text-align: center;
  padding-bottom: 16px;
}
.accessory-card .card-image {
  height: 200px;
  background: #f5f5f7;
}
.accessory-card .card-image i { font-size: 48px; color: #1d1d1f; opacity: .5; }
.accessory-card .card-body { padding: 12px 16px; }
.accessory-card .card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.3; }
.accessory-card .card-body .price { font-size: 14px; font-weight: 600; margin-top: 4px; }

/* --- Audio Card --- */
.audio-card {
  flex: 0 0 240px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
}
.audio-card .card-image {
  height: 240px;
}
.audio-card .card-image i { font-size: 64px; opacity: .6; }
.audio-card .card-body { padding: 16px 20px; }
.audio-card .card-body h4 { font-size: 14px; font-weight: 600; line-height: 1.3; }
.audio-card .card-body .price { font-size: 14px; font-weight: 600; margin-top: 4px; }
.audio-card .card-body .note { font-size: 12px; color: #6e6e73; margin-top: 2px; }

/* --- Model Cards (category pages) --- */
.model-card {
  flex: 0 0 300px;
  border-radius: 18px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,.08);
  text-align: center;
}
.model-card .card-image { height: 300px; }
.model-card .card-image i { font-size: 80px; opacity: .6; }
.model-card .card-body { padding: 20px 24px 28px; }
.model-card .card-body .badge-new { margin-bottom: 4px; }
.model-card .card-body h4 { font-size: 21px; font-weight: 600; margin-bottom: 4px; }
.model-card .card-body .price { font-size: 17px; font-weight: 600; }
.model-card .card-body .price-monthly { font-size: 14px; color: #6e6e73; margin-top: 2px; }
.model-card .card-body .card-links { margin-top: 12px; display: flex; justify-content: center; gap: 16px; }

/* --- Experience Section --- */
.experience-section {
  text-align: center;
  padding: 80px 22px;
  background: #f5f5f7;
}
.experience-section h2 { font-size: 40px; font-weight: 700; }
.experience-section p { font-size: 21px; color: #6e6e73; margin-top: 6px; }
.experience-features {
  display: flex;
  justify-content: center;
  gap: 40px;
  margin-top: 40px;
  flex-wrap: wrap;
}
.experience-feature {
  text-align: center;
  max-width: 200px;
}
.experience-feature i { font-size: 40px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.experience-feature h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.experience-feature p { font-size: 14px; color: #6e6e73; }

/* --- Special Stores --- */
.special-stores-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.special-store-card {
  border-radius: 18px;
  background: #f5f5f7;
  padding: 32px 24px;
  text-align: center;
}
.special-store-card i { font-size: 36px; margin-bottom: 12px; display: block; color: #1d1d1f; }
.special-store-card h4 { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.special-store-card p { font-size: 14px; color: #6e6e73; line-height: 1.4; }
.special-store-card a { font-size: 14px; margin-top: 8px; display: inline-block; }

@media (max-width: 768px) {
  .special-stores-grid { grid-template-columns: 1fr; }
}

/* --- Category Page Sections --- */
.category-section {
  padding: 60px 0;
  scroll-margin-top: 90px;
}
.category-section:nth-child(even) { background: #f5f5f7; }

/* --- Utility --- */
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
.link-blue { color: #0066cc; }
.link-white { color: #2997ff; }

raw_arguments.content:
/* ========================================
   Orchard — Premium Tech E-Commerce Store
   ======================================== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: #1d1d1f;
  background: #fff;
  line-height: 1.47059;
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: #0066cc; text-decoration: none; }
a:hover { text-decoration: underline; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* --- Typography --- */
.headline { font-size: 56px; font-weight: 700; letter-spacing: -0.005em; line-height: 1.07143; }
.headline-sm { font-size: 48px; font-weight: 700; letter-spacing: -0.003em; line-height: 1.08349; }
.subheadline { font-size: 28px; font-weight: 400; letter-spacing: .011em; line-height: 1.10722; color: #6e6e73; }
.subheadline-sm { font-size: 21px; font-weight: 400; line-height: 1.381; color: #6e6e73; }
.section-eyebrow { font-size: 12px; font-weight: 600; letter-spacing: -.01em; text-transform: uppercase; color: #6e6e73; margin-bottom: 4px; }
.badge-new { display: inline-block; font-size: 12px; font-weight: 600; color: #bf4800; letter-spacing: -.01em; margin-bottom: 2px; }
