}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 22px;
}
.carousel-track {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding: 4px 0 20px;
}
.carousel-track::-webkit-scrollbar { display: none; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-60%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,.9);
  box-shadow: 0 1px 4px rgba(0,0,0,.16);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: opacity .3s, transform .2s;
  font-size: 20px;
  color: #1d1d1f;
}
.carousel-arrow:hover { transform: translateY(-60%) scale(1.06); }
.carousel-arrow-left { left: 4px; }
.carousel-arrow-right { right: 4px; }
.carousel-arrow.hidden { opacity: 0; pointer-events: none; }

/* --- Carousel Cards --- */
.carousel-card {
  flex: 0 0 280px;
