.card-body { padding: 20px; }
.card-body .badge-new { margin-bottom: 4px; }
.card-body h4 { font-size: 17px; font-weight: 600; line-height: 1.3; margin-bottom: 2px; }
.card-body .card-tagline { font-size: 14px; color: #6e6e73; margin-bottom: 8px; line-height: 1.3; }
.card-body .price { font-size: 14px; font-weight: 600; }
.card-body .price-monthly { font-size: 12px; color: #6e6e73; margin-top: 2px; }
.card-body .card-links { margin-top: 10px; display: flex; gap: 16px; }
