/* Footer accordion on mobile */
@media (max-width: 834px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col { border-bottom: 1px solid #d2d2d7; }
  .footer-col h5 {
    padding: 12px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }
  .footer-col h5::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform .3s;
  }
  .footer-col.open h5::after { content: '−'; }
  .footer-col ul {
